%[text] 发现2:Transfer 过程是layer 2为模版的，L2编码了早期的记忆，晚期的动作目的，并在迁移过程中共用了L2，而L5参与了行为
%[text:tableOfContents]{"heading":"目录"}
%[text] # 学习早期
%[text] 2层功能：记录刺激
%[text] 1. 时间提前
%[text] 2. 活动低
%[text] 3. 对cue不响应 \
%[text] L5无时间提前
%[text] L2早于L5
%[text] ## A
%[text] 群体活动总览：1s内达到基线3倍标准差的所有细胞
ALB=TransferLearning.AudioLightBaseline;
QueryTablePath=TransferLearning.ProjectPath('查询表.xlsx');
%%
EnsembleA=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2A'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:7fb1b0a6]
[~,Index]=ismember(EnsembleA.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
%%
EnsembleLogical=max(EnsembleA.NTATS.AudioWater(:,25:32),[],2)>std(EnsembleA.NTATS.AudioWater(:,1:24),[],2)*3;
Layer2Logical=ZLayer=="MOp2/3";
Layer5Logical=ZLayer=="MOp5";
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
%%
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["AudioOnly","WaterOnly","AudioWater"];
HLData=table;
HLData.(LayerTitles(1))=permute(EnsembleA.NTATS{Ensemble2,:,Phases},[3,1,2]);
HLData.(LayerTitles(2))=permute(EnsembleA.NTATS{Ensemble5,:,Phases},[3,1,2]);
HLData.Properties.RowNames=Phases';
%%
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=":k";
XLine.Time=seconds(0);
Fig=figure; %[output:3395302a]
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(HLData(:,LayerTitles),seconds([-3,3]),XLine=XLine); %[output:3395302a]
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1))); %[output:3395302a]
ylabel(Axes(3,1),'z-score ± SEM'); %[output:3395302a]
ColorBar.Label.String='z-score'; %[output:3395302a]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:3395302a]
title(Layout,'Ensemble Naive'); %[output:3395302a]
print(Fig,TransferLearning.ProjectPath('Fig2A.svg'),'-dsvg'); %[output:3395302a]
%%
%[text] ## B
Fig=figure; %[output:1e4f60dc]
Layout=tiledlayout(2,2,TileSpacing='tight',Padding='compact');%Padding如果用tight，右边坐标轴会出界 %[output:1e4f60dc]
%%
%[text] 2层时间提前：AudioWater相比于AudioOnly
EnsembleB12=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B12'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:783df95b]
%%
BaselineB=std(EnsembleB12.NTATS(:,1:24,:),[],2).*3;
%%
[Logical,Time]=max(EnsembleB12.NTATS(:,25:end,:)>BaselineB,[],2);
EnsembleLogical=Logical.AudioWater&Time.AudioWater<=8;
BothRisingLogical=Logical.AudioOnly&EnsembleLogical;
Time=Time(BothRisingLogical,:,:);
Time.Data=Time.Data*milliseconds(125);
Time=table(Time.AudioOnly,Time.AudioWater,'VariableNames',["🔊","🔊💧"]);
%%
nexttile; %[output:74f609e2]
UniExp.BarScatterCompare(Time,false,table(["🔊","🔊💧"],'VariableNames',"GroupPair")); %[output:74f609e2]
ylabel('Rising time (s)'); %[output:74f609e2]
title(MATLAB.SignificantFixedpoint(sum(BothRisingLogical)/sum(EnsembleLogical)*100,2)+"% L2 ensemble"); %[output:74f609e2]
YLim=ylim;
ylim([0,YLim(2)]); %[output:74f609e2]
%%
%[text] 2层活动强度：AudioWater比AudioOnly强
Response=max(EnsembleB12.NTATS(:,25:32,:),[],2);
ResponseLogical=Response.AudioWater>BaselineB.AudioWater;
Response=Response(ResponseLogical,:,:);
nexttile; %[output:9213e868]
UniExp.BarScatterCompare(table(Response.AudioOnly,Response.AudioWater,'VariableNames',["🔊","🔊💧"]),false,table(["🔊","🔊💧"],'VariableNames',"GroupPair")); %[output:9213e868]
ylabel('Max z-score in 1s'); %[output:9213e868]
%此图包含2层群体全部细胞
YLim=ylim;
ylim([0,YLim(2)]); %[output:9213e868]
%%
%[text] 5层：AudioWater与WaterOnly时间比较
EnsembleB3=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B3'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:3dd5a852]
%%
[Rising,Time]=max(EnsembleB3.NTATS(:,25:end,:)>std(EnsembleB3.NTATS(:,1:24,:),[],2).*3,[],2);
%%
EnsembleLogical=Rising.AudioWater&Time.AudioWater<=8;
BothRisingLogical=EnsembleLogical&Rising.WaterOnly;
%%
Time=Time(BothRisingLogical,:,:);
Time.Data=Time.Data*milliseconds(125);
%%
nexttile; %[output:62ba9d9e]
UniExp.BarScatterCompare(table(Time.WaterOnly,Time.AudioWater,'VariableNames',["💧","🔊💧"]),false,table(["💧","🔊💧"],'VariableNames',"GroupPair")); %[output:62ba9d9e]
ylabel('Rising time (s)'); %[output:62ba9d9e]
title(MATLAB.SignificantFixedpoint(sum(BothRisingLogical)/sum(EnsembleLogical)*100,2)+"% L5 ensemble"); %[output:62ba9d9e]
YLim=ylim;
ylim([0,YLim(2)]); %[output:62ba9d9e]
%%
%[text] L2早于L5
EnsembleB4=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B4'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:2e48323b]
%%
RisingTime=struct;
Proportion=struct;
for L=["Layer2","Layer5"]
	NTATS=EnsembleB4.(L).NTATS;
	[Rising,Time]=max(NTATS(:,25:end)>std(NTATS(:,1:24),[],2)*3,[],2);
	RisingTime.(L)=Time(Rising)*milliseconds(125);
	Proportion.(L)=MATLAB.SignificantFixedpoint(mean(Rising)*100,2)+"%";
end
%%
nexttile; %[output:7fd71856]
%%
UniExp.BarScatterCompare(RisingTime,false,table(["Layer2","Layer5"],'VariableNames',"GroupPair")); %[output:6c4a228d]
ylabel('Rising time (s)'); %[output:6c4a228d]
xticklabels(fieldnames(Proportion).'+" "+struct2array(Proportion)); %[output:6c4a228d]
YLim=ylim;
ylim([0,YLim(2)]); %[output:6c4a228d]
%%
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow);
%%
Layout.Padding="compact"; %[output:5b303270]
print(Fig,TransferLearning.ProjectPath('Fig2B.svg'),'-dsvg'); %[output:5b303270]
%%
%[text] # 学习后
%[text] L2功能：指导L5行动
%[text] 1. 时间提前
%[text] 2. 活动高
%[text] 3. 形成correlation ensemble？ \
%[text] L5
%[text] 1. 时间提前
%[text] 2. 响应增强 \
%[text] L2与L5 同时
%[text] ## C
EnsembleCD=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2CD'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:7583b186]
%%
EnsembleC=UniExp.NtatsCellStrip(EnsembleCD);
%%
[~,Index]=ismember(EnsembleC.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
Layer5Logical=ZLayer=="MOp5";
Layer2Logical=~Layer5Logical;
%%
EnsembleLogical=max(EnsembleC.NTATS.Learned(:,25:32),[],2)>std(EnsembleC.NTATS.Learned(:,1:24),[],2)*3;
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["Naive","Learned"];
%%
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=[":k";"-k"];
XLine.Time=seconds([0;1]);
%%
Fig=figure; %[output:9305bb70]
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(table(permute(EnsembleC.NTATS{Ensemble2,:,Phases},[3,1,2]),permute(EnsembleC.NTATS{Ensemble5,:,Phases},[3,1,2]),'VariableNames',LayerTitles,'RowNames',Phases),seconds([-3,3]),XLine=XLine); %[output:9305bb70]
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1))); %[output:9305bb70]
ylabel(Axes(3,1),'z-score ± SEM'); %[output:9305bb70]
ColorBar.Label.String='z-score'; %[output:9305bb70]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:9305bb70]
title(Layout,'Ensemble Learned') %[output:9305bb70]
print(Fig,TransferLearning.ProjectPath('Fig2C.svg'),'-dsvg'); %[output:9305bb70]
%%
%[text] ## D
EnsembleCD.Naive.Phase(:)="Naive";
EnsembleCD.Learned.Phase(:)="Learned";
EnsembleD=[EnsembleCD.Naive;EnsembleCD.Learned];
[~,Index]=ismember(EnsembleD.CellUID,ALB.Cells.CellUID);
Ensemble.ZLayer=ALB.Cells.ZLayer(Index);
ZLayerCount=groupsummary(EnsembleD,'ZLayer');
[Rising,Time]=max(EnsembleD.NTATS(:,25:end)>std(EnsembleD.NTATS(:,1:24),[],2)*3,[],2);
EnsembleD=EnsembleD(Rising,:);
EnsembleD.RisingTime=Time(Rising)*milliseconds(125);
PhaseLayerRising=groupsummary(EnsembleD,["Phase","ZLayer"],"mean","RisingTime");



